#include <stdio.h>

int main() {
    int arr[3] = {10, 20, 30};

    // Pointer to an Array of 3 integers
    int (*p)[3] = &arr;

    // Array of Pointers (Different!)
    int *ptrArr[3];
    ptrArr[0] = &arr[0];

    printf("*(*p + 1) = %d\n", *(*p + 1)); // Access arr[1]

    return 0;
}
